//! Raw FFI bindings to libghostty-vt, generated by bindgen at build time.
//!
//! This crate is the *only* place in the workspace where `unsafe` is allowed
//! at the lint level. All higher-level crates (`host-ghostty`, `host-pty`,
//! etc.) wrap these bindings in safe Rust types and forbid unsafe themselves.
//!
//! See `docs/solutions/2026-04-12-libghostty-linux-spike.md` for the spike
//! that validated this embedding path.

#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(dead_code)]
#![allow(clippy::all)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
